    'surprise.savitskiyTitle': "Savitskiy Museum, Nukus",
    'surprise.savitskiyDesc': "Called the \"Louvre of the Desert\" — home to one of the world's finest collections of Russian avant-garde art and ancient Karakalpak treasures.",
    'surprise.ustyurtTitle': "Ustyurt Plateau",
    'surprise.ustyurtDesc': "Dramatic chalk cliffs, sweeping canyon vistas, and otherworldly white rock formations. A paradise for adventure seekers and photographers.",
    'surprise.chilpekTitle': "Chilpek Dakhma",
    'surprise.chilpekDesc': "An ancient Zoroastrian Tower of Silence on a sacred hilltop near Nukus. Mystical ruins with panoramic views of the surrounding desert.",
    'surprise.sudochyeTitle': "Lake Sudochye",
    'surprise.sudochyeDesc': "A shimmering oasis wetland teeming with migratory birds. Once part of the Aral Sea, now a serene lake fringed by reeds and desert steppe.",
