    'essentials.subtitle': "Everything you need to know before you go",
    'essentials.sim': "SIM Cards",
    'essentials.simDesc': "Buy a local SIM at Nukus Airport or any Beeline/Ucell shop. You'll need your passport. A tourist SIM costs about 20,000–30,000 UZS.",
    'essentials.cards': "Visa & Mastercard",
    'essentials.cardsDesc': "Major cards work in Nukus hotels and restaurants. Carry cash for rural areas, yurt camps, and markets — card acceptance is limited outside the city.",
    'essentials.currency': "Local Currency",
    'essentials.currencyDesc': "The Uzbek Som (UZS) is the local currency. Exchange at banks or official exchange booths. Avoid street money changers.",
    'essentials.registration': "Registration Rules",
    'essentials.registrationDesc': "If staying more than 3 days, your hotel must register you with the migration service. Keep your registration slips — you may need them at departure.",
    'essentials.etiquette': "Local Etiquette",
    'essentials.etiquetteDesc': "Dress modestly at religious sites. Remove shoes when entering homes. Use your right hand for eating and greeting. Ask before photographing people.",
    'essentials.health': "Health & Safety",
